import sys

n = int(sys.stdin.read().split()[0])
if n <= 3000:
    state = [False] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i, n + 1, i):
            state[j] = not state[j]
    print(sum(state))
else:
    r = 0
    while (r + 1) * (r + 1) <= n:
        r += 1
    print(r)

